  setActivePinia(createPinia())
  tasksApiMock.get.mockResolvedValue(detail)
  const props: Record<string, unknown> = {
    modelValue: false,
    taskId: 'task-1',
  }
  if (canManage !== undefined) props.canManage = canManage
