/* result drawer */
.result-scrim{
  position:fixed;inset:0;z-index:135;
  background:rgba(20,27,32,.42);
  opacity:0;pointer-events:none;transition:opacity .2s;
}
.result-scrim.is-open{opacity:1;pointer-events:auto}
.result-drawer{
  position:fixed;right:0;top:0;bottom:0;z-index:140;
  display:flex;flex-direction:column;
  width:min(520px,94vw);
  background:var(--surface);
  border-left:1px solid var(--line);
  box-shadow:-24px 0 48px -32px rgba(0,0,0,.45);
  transform:translateX(102%);
  transition:transform .24s ease;
  outline:none;
}
.result-drawer.is-open{transform:none}
.result-head{
  flex:none;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;
  padding:16px 20px;border-bottom:1px solid var(--line);
}
.result-head h2{font-size:15px;font-weight:650;letter-spacing:-.01em}
.result-sub{margin-top:3px;font-size:10.5px;color:var(--ink-3)}
.result-sub .mono{font-size:10px}
.result-body{flex:1;min-height:0;overflow-y:auto;padding:18px 20px 24px}
.result-foot{
  flex:none;display:flex;align-items:center;gap:10px;
  padding:10px 20px;border-top:1px solid var(--line);
  background:var(--surface-2);
  font-size:9.5px;color:var(--ink-3);
}
.result-foot .spacer{flex:1}
.result-foot .text-link{font-size:10.5px}
.res-summary{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  padding-bottom:12px;border-bottom:1px solid var(--line-2);
  font-size:11px;color:var(--ink-3);
}
.res-note{margin-top:10px;font-size:10.5px;line-height:1.6;color:var(--ink-3)}
.res-section{margin-top:16px}
.res-section h3{font-size:11.5px;font-weight:600;color:var(--ink-2);letter-spacing:.01em;margin-bottom:8px}
.res-item{display:grid;grid-template-columns:26px minmax(0,1fr);gap:8px;padding:9px 0;border-top:1px solid var(--line-2)}
.res-num{font-family:var(--font-mono);font-size:9.5px;color:var(--ink-3);padding-top:2px}
.res-quote{font-size:11.5px;line-height:1.6;color:var(--ink)}
.res-suggestion{margin-top:3px;font-size:11px;line-height:1.6;color:var(--ink-3)}
.res-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:4px}
