.res-table td{padding:7px 4px;border-bottom:1px solid var(--line-2);color:var(--ink-2)}
.res-table td.num{text-align:right;font-family:var(--font-mono);font-size:10px}
.res-ok{color:var(--green)}
.res-warn{color:var(--amber-text)}
.res-stat-row{
  display:flex;gap:28px;margin-top:12px;padding:12px 14px;
