.res-error{
  margin-top:12px;padding:10px 12px;border:1px solid var(--red-soft);border-radius:6px;
  background:var(--red-soft);font-size:11px;line-height:1.6;color:var(--red);
}
.res-error .mono{font-size:10px}
.res-raw{margin-top:16px;padding-top:10px;border-top:1px solid var(--line-2)}
