/**
 * A2A 授权链接前端校验（M7）。
 *
 * 后端 M7 对 `authorization_url` 做白名单：只允许 https，dev/test 额外允许
 * `http://localhost`、`http://127.0.0.1`，非法协议/内网/超长一律置 `null`。
 * 前端不重复实现「内网判定」策略，只保留与之一致的最小防线：
 * 协议白名单 + 本地回环 http，非法链接不渲染成可点击按钮。
 */
export function isSafeAuthorizationUrl(url: string | null | undefined): boolean {
  if (!url) return false
  if (url.length > 2000) return false
  try {
    const parsed = new URL(url)
    if (parsed.protocol === 'https:') return true
    if (parsed.protocol === 'http:') {
      return parsed.hostname === '127.0.0.1' || parsed.hostname === 'localhost'
    }
    return false
  } catch {
    return false
  }
}
import dayjs from 'dayjs'
import relativeTime from 'dayjs/plugin/relativeTime'
import 'dayjs/locale/zh-cn'

dayjs.extend(relativeTime)
dayjs.locale('zh-cn')

export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return ''
  const date = dayjs(iso)
  if (!date.isValid()) return ''
  const now = dayjs()
  if (date.isSame(now, 'day')) return date.format('HH:mm')
  if (date.isSame(now.subtract(1, 'day'), 'day')) return '昨天'
  if (date.isAfter(now.subtract(7, 'day'))) return date.format('dddd')
  return date.format('MM-DD')
}

export function formatDateTime(iso: string | null | undefined): string {
  if (!iso) return '—'
  const date = dayjs(iso)
  return date.isValid() ? date.format('YYYY-MM-DD HH:mm') : '—'
}

export function formatTime(iso: string | null | undefined): string {
  if (!iso) return '—'
  const date = dayjs(iso)
  return date.isValid() ? date.format('HH:mm:ss') : '—'
}

/** 消息/审批卡头部的钟点：只到分钟（原型 <time>22:41</time>）。 */
export function formatClock(iso: string | null | undefined): string {
  if (!iso) return ''
  const date = dayjs(iso)
  return date.isValid() ? date.format('HH:mm') : ''
}

export function formatDuration(ms: number | null | undefined): string {
  if (ms === null || ms === undefined) return '—'
  if (ms < 1000) return `${Math.round(ms)}ms`
  return `${(ms / 1000).toFixed(1)}s`
}

export function formatTokens(value: number | null | undefined): string {
  if (value === null || value === undefined) return '—'
  if (value >= 1000) return `${(value / 1000).toFixed(1)}k`
  return String(value)
}

export function formatBytes(bytes: number | null | undefined): string {
  if (bytes === null || bytes === undefined) return '—'
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

