          <summary>请求参数</summary>
          <pre class="res-json">{{ argsJson }}</pre>
        </details>
      </section>

      <section v-if="detail.result" class="res-section">
        <h3>结果</h3>
        <p class="res-note">{{ detail.result.summary }}</p>
        <template v-if="detail.result.artifact.summary">
