import { chromium } from '@playwright/test'
const ROOT = '/home/zhaodan/work/NodeJsProjects/agent-hub-web'
const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await ctx.newPage()

const measureFn = () => {
  const pick = (sel, props = ['x','y','w','h']) => {
    const el = document.querySelector(sel)
    if (!el) return null
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    const out = {}
    for (const p of props) {
      if (p === 'x') out.x = Math.round(r.x)
      else if (p === 'y') out.y = Math.round(r.y)
      else if (p === 'w') out.w = Math.round(r.width)
      else if (p === 'h') out.h = Math.round(r.height)
      else out[p] = cs[p]
    }
    return out
  }
  return {
    sidebar: pick('.sidebar'),
    page: pick('.page'),
    pageHead: pick('.page-head'),
    title: pick('.page-title', ['x','y','w','h','fontSize','fontWeight','lineHeight']),
    sub: pick('.page-sub', ['x','y','w','h','fontSize']),
    refresh: pick('.page-actions .btn'),
    stats: pick('.stats'),
    stat1: pick('.stat'),
    statValue: pick('.stat-value'),
    statLabel: pick('.stat-label'),
    toolbar: pick('.toolbar'),
    seg: pick('.seg'),
    segBtn: pick('.seg button'),
    search: pick('.tool-search'),
    taskHead: pick('.task-head'),
    taskRow: pick('.task-summary'),
    taskId: pick('.task-id'),
    taskAgent: pick('.task-agent'),
    st: pick('.task-summary .st'),
    duration: pick('.task-duration'),
    conv: pick('.task-conv'),
    detail: pick('.task-detail'),
    detailH4: pick('.task-detail h4'),
    kv: pick('.task-detail .kv'),
    timeline: pick('.task-timeline'),
    btnSm: pick('.detail-actions .btn-sm', ['x','y','w','h','fontSize']),
  }
}

// proto
await page.goto(`file://${ROOT}/docs/prototypes/ui-v7-pages.html`)
await page.waitForTimeout(600)
await page.evaluate(() => {
  document.querySelectorAll('.page[data-page]').forEach((el) => {
    el.hidden = el.getAttribute('data-page') !== 'tasks'
  })
})
await page.waitForTimeout(400)
const proto = await page.evaluate(measureFn)
console.log('PROTO', JSON.stringify(proto, null, 1))

// app
await page.goto('http://127.0.0.1:5174/login', { waitUntil: 'domcontentloaded' })
await page.getByPlaceholder('you@example.com').fill('admin@example.com')
await page.getByPlaceholder('至少 8 位').fill('12345678')
await page.getByRole('button', { name: '登录', exact: true }).click()
await page.waitForURL(/\/chat/, { timeout: 20000 })
await page.goto('http://127.0.0.1:5174/tasks', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)
const app = await page.evaluate(measureFn)
console.log('APP', JSON.stringify(app, null, 1))
await browser.close()
EOF
